      {
        "judulBab": "Panel 2 · Kata Ajaib: Tolong, Maaf, Terima Kasih",
        "isi": "Saat meminta bantuan teman mengambilkan buku, ia berkata \"tolong\". Ketika menerima bantuan, ia mengucap \"terima kasih\", dan berani berkata \"maaf\" bila berbuat keliru."
      },
      {
        "judulBab": "Panel 3 · Bernyanyi & Mempraktikkan Kebaikan",
        "isi": "Di akhir komik, seluruh teman di PAUD ikut menyanyikan lagu ceria tentang karakter jujur, sopan, dan suka menolong di rumah maupun rumah baca.",
        "pesanMoral": "Tiga kata ajaib — tolong, maaf, dan terima kasih — membuat teras bermain semakin akrab."
      }
